"use client"

import { useState, useEffect, Suspense } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Loader2, ArrowLeft, Sparkles } from "lucide-react"
import Link from "next/link"
import { toast } from "sonner"

const categoryOptions = [
  { value: "electronics", label: "电子产品" },
  { value: "clothing", label: "服装鞋帽" },
  { value: "home", label: "家居园艺" },
  { value: "beauty", label: "美容个护" },
  { value: "sports", label: "运动户外" },
  { value: "toys", label: "玩具游戏" },
  { value: "food", label: "食品饮料" },
  { value: "other", label: "其他" },
]

const platformOptions = [
  { value: "amazon", label: "Amazon" },
  { value: "shopify", label: "Shopify" },
  { value: "tiktok", label: "TikTok Shop" },
]

const languageOptions = [
  { value: "zh", label: "中文" },
  { value: "en", label: "English" },
  { value: "es", label: "Español" },
]

const brandToneOptions = [
  { value: "professional", label: "专业权威" },
  { value: "fashionable", label: "时尚潮流" },
  { value: "friendly", label: "亲切友好" },
  { value: "luxury", label: "高端奢华" },
  { value: "humorous", label: "幽默风趣" },
]

const priceRangeOptions = [
  { value: "budget", label: "经济型 ($10-30)" },
  { value: "mid", label: "中端 ($30-60)" },
  { value: "mid-high", label: "中高端 ($60-100)" },
  { value: "high", label: "高端 ($100+)" },
]

type PrefillData = {
  productName: string
  category: string | null
  features: string | null
  sellingPoints: string | null
  keywords: string | null
  useScenario: string | null
  targetAudience: string | null
  priceRange: string | null
  brandTone: string | null
  platform: string
  language: string
}

function LoadingSkeleton() {
  return (
    <div className="mx-auto max-w-3xl px-4 sm:px-6 lg:px-8 py-8">
      <div className="animate-pulse space-y-4">
        <div className="h-5 bg-muted rounded w-24" />
        <div className="h-8 bg-muted rounded w-48" />
        <div className="h-4 bg-muted rounded w-96" />
        <div className="h-96 bg-muted rounded" />
      </div>
    </div>
  )
}

function NewProjectForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [loading, setLoading] = useState(false)
  const reuseProjectId = searchParams.get("reuseProjectId")
  const [prefillLoading, setPrefillLoading] = useState(!!reuseProjectId)
  const [prefillData, setPrefillData] = useState<PrefillData | null>(null)

  useEffect(() => {
    if (!reuseProjectId) return

    fetch(`/api/projects/${reuseProjectId}`)
      .then((res) => {
        if (!res.ok) throw new Error("项目不存在")
        return res.json()
      })
      .then((data) => {
        setPrefillData(data.project)
        setPrefillLoading(false)
      })
      .catch(() => {
        toast.error("项目不存在或已删除")
        router.replace("/dashboard/new")
      })
  }, [reuseProjectId, router])

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    setLoading(true)

    const form = new FormData(e.currentTarget)
    const data = {
      productName: form.get("productName"),
      category: form.get("category") || null,
      features: form.get("features") || null,
      sellingPoints: form.get("sellingPoints") || null,
      keywords: form.get("keywords") || null,
      useScenario: form.get("useScenario") || null,
      targetAudience: form.get("targetAudience") || null,
      priceRange: form.get("priceRange") || null,
      brandTone: form.get("brandTone") || null,
      platform: form.get("platform"),
      language: form.get("language"),
    }

    const res = await fetch("/api/projects", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    })

    const result = await res.json()

    if (!res.ok) {
      toast.error(result.error || "创建失败")
      setLoading(false)
      return
    }

    toast.success("项目创建成功！")
    router.push(`/dashboard/${result.project.id}`)
  }

  if (prefillLoading) return <LoadingSkeleton />

  return (
    <div className="mx-auto max-w-3xl px-4 sm:px-6 lg:px-8 py-8">
      {/* Back */}
      <Link
        href="/dashboard"
        className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground transition-colors mb-6"
      >
        <ArrowLeft className="size-4" />
        返回工作台
      </Link>

      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold tracking-tight">
          {reuseProjectId ? "复用项目" : "新建项目"}
        </h1>
        <p className="text-sm text-muted-foreground mt-1">
          {reuseProjectId
            ? "基于已有项目的信息创建新项目，你可以修改后再提交"
            : "填写产品信息，AI 将为你生成适配的文案和图片"}
        </p>
      </div>

      <form
        key={reuseProjectId || "new"}
        onSubmit={handleSubmit}
        className="space-y-10"
      >
        {/* Basic Info */}
        <section>
          <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-4">
            基本信息
          </h2>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="productName">
                产品名称 <span className="text-destructive">*</span>
              </Label>
              <Input
                id="productName"
                name="productName"
                placeholder="例如：无线蓝牙耳机"
                required
                defaultValue={prefillData?.productName || ""}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="category">产品品类</Label>
              <Select
                name="category"
                defaultValue={prefillData?.category || undefined}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择品类" />
                </SelectTrigger>
                <SelectContent>
                  {categoryOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </section>

        {/* Product Details */}
        <section>
          <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-4">
            产品详情
          </h2>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="features">产品特点</Label>
              <Textarea
                id="features"
                name="features"
                placeholder="描述产品的核心特点和功能，用逗号或换行分隔"
                rows={3}
                defaultValue={prefillData?.features || ""}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sellingPoints">核心卖点</Label>
              <Textarea
                id="sellingPoints"
                name="sellingPoints"
                placeholder="产品的主要卖点和差异化优势"
                rows={3}
                defaultValue={prefillData?.sellingPoints || ""}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="keywords">关键词</Label>
              <Textarea
                id="keywords"
                name="keywords"
                placeholder="相关搜索关键词，用逗号分隔"
                rows={2}
                defaultValue={prefillData?.keywords || ""}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="useScenario">使用场景</Label>
              <Textarea
                id="useScenario"
                name="useScenario"
                placeholder="产品的主要使用场景和应用环境"
                rows={2}
                defaultValue={prefillData?.useScenario || ""}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="targetAudience">目标人群</Label>
              <Input
                id="targetAudience"
                name="targetAudience"
                placeholder="例如：18-35岁年轻消费者"
                defaultValue={prefillData?.targetAudience || ""}
              />
            </div>
          </div>
        </section>

        {/* Positioning */}
        <section>
          <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-4">
            定位与风格
          </h2>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="priceRange">价格区间</Label>
              <Select
                name="priceRange"
                defaultValue={prefillData?.priceRange || undefined}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择价格区间" />
                </SelectTrigger>
                <SelectContent>
                  {priceRangeOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="brandTone">品牌调性</Label>
              <Select
                name="brandTone"
                defaultValue={prefillData?.brandTone || undefined}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择品牌调性" />
                </SelectTrigger>
                <SelectContent>
                  {brandToneOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </section>

        {/* Platform & Language */}
        <section>
          <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-4">
            目标平台与语言
          </h2>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="platform">
                目标平台 <span className="text-destructive">*</span>
              </Label>
              <Select
                name="platform"
                required
                defaultValue={prefillData?.platform || undefined}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择平台" />
                </SelectTrigger>
                <SelectContent>
                  {platformOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="language">
                生成语言 <span className="text-destructive">*</span>
              </Label>
              <Select
                name="language"
                required
                defaultValue={prefillData?.language || undefined}
              >
                <SelectTrigger>
                  <SelectValue placeholder="选择语言" />
                </SelectTrigger>
                <SelectContent>
                  {languageOptions.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </section>

        {/* Submit */}
        <div className="flex items-center gap-3 pt-4 border-t border-border/40">
          <Button type="submit" size="lg" className="gap-2" disabled={loading}>
            {loading ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <Sparkles className="size-4" />
            )}
            {loading ? "创建中..." : "创建项目"}
          </Button>
          <Button
            type="button"
            variant="outline"
            size="lg"
            onClick={() => router.push("/dashboard")}
            disabled={loading}
          >
            取消
          </Button>
        </div>
      </form>
    </div>
  )
}

export default function NewProjectPage() {
  return (
    <Suspense fallback={<LoadingSkeleton />}>
      <NewProjectForm />
    </Suspense>
  )
}
